package com.example.rokidgeminisecretary;
import org.json.*;
/** Observed states only; never predicts model completion or changes the queue. */
final class ConversationWait {
 static boolean pending(JSONObject row){return row!=null&&row.optBoolean("tracked")&&row.optString("requestState").matches("CREATED|QUEUED|RECEIVED|RUNNING");}
 static String reason(JSONObject row,JSONArray all,JSONObject runtime,long elapsed){String state=row.optString("requestState");if(!pending(row))return "処理は完了または結果確認が必要です";if(state.equals("QUEUED")&&runtime!=null&&runtime.optJSONObject("reconnect")!=null&&runtime.optJSONObject("reconnect").optJSONArray("held")!=null){JSONArray held=runtime.optJSONObject("reconnect").optJSONArray("held");for(int i=0;i<held.length();i++)if(row.optString("key").equals(held.optString(i)))return "接続復帰後の内容確認待ちです。送信状況から、この質問の送信を許可してください";}if(state.equals("CREATED"))return "スマホで受付を保存しています";if(runtime==null||!runtime.optBoolean("contactRecent")||!runtime.optBoolean("stateFresh")||elapsed>=15000)return "メガネの接続・処理状態を確認中です（完了時刻は未確認）";if(state.equals("RUNNING"))return "AIの回答処理中です。検索などを含む場合があります。完了時刻は未確認です";if(state.equals("RECEIVED"))return "メガネで受理済み・処理開始を確認中です";for(int i=0;i<all.length();i++){JSONObject other=all.optJSONObject(i);if(other!=null&&other.optBoolean("tracked")&&!other.optString("key").equals(row.optString("key"))&&other.optLong("time")<=row.optLong("time")&&other.optString("requestState").matches("RECEIVED|RUNNING"))return "前の質問の完了待ちです。新しい質問は送信待ちに保持しています";}long wait=runtime.optLong("waitMs")-Math.max(0,elapsed);if(wait>0)return (runtime.optString("message").contains("API再試行")?"API再試行の待機：":"送信間隔の待機：")+"次回送信まで最短約"+((wait+999)/1000)+"秒（回答の完了予測ではありません）";return "メガネへの引き渡し・メガネ側の処理終了を確認中です";}
 static String latest(MainActivity owner)throws Exception{JSONArray rows=ConversationContinuation.ledger(owner);JSONObject latest=null;for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(pending(row)&&(latest==null||row.optLong("time")>latest.optLong("time")))latest=row;}return latest==null?"":reason(latest,rows,owner.webConversationRuntime(),0);}
 private ConversationWait(){}
}
